import {supplyPlan,needsSupply,supplyTarget} from './workshop-supply.js?v=0.7.2';
import {orderBike} from './workshop-orders.js?v=0.7.2';
import {euro} from './data.js?v=0.7.2';
import {WORKSHOP_TYPES,WORKSHOP_TRAINING,workshopHours,workshopEstimate,workshopStep,workshopSteps,workshopPayout} from './workshop.js?v=0.7.2';
import {WORKSHOP_POINTS,atWorkshop} from './workshop-layout.js?v=0.7.2';
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const level=w=>['Aushilfe','Zweirad-Basiskurs','Sicheres Arbeiten'][w.training];
const hours=s=>`<div class="cafe-hours ${workshopHours(s).accept?'open':'closed'}"><strong>${workshopHours(s).accept?'Aufträge werden angenommen':workshopHours(s).open?'Annahme geschlossen · laufende Arbeiten abschließen':'Heute geschlossen'}</strong><span>Geöffnet 08:00–19:00 · neue Aufträge bis 17:00</span></div>`;
export function workshopReceipt(w){const r=w.last;if(!r)return '';return `<section class="courier-receipt"><span class="eyebrow">LETZTE ARBEITSABRECHNUNG · TAG ${r.day}</span><h3>${WORKSHOP_TYPES[r.type].name}</h3><p>${r.status==='completed'?'Von Tessa abgenommen':r.status==='expired'?'Zum Ladenschluss beendet':'Ohne Abnahme zurückgegeben'} · ${r.mistakes} Nacharbeiten${r.minutes!=null?` · ${r.minutes} Spielminuten insgesamt`:``}${r.workMinutes!=null?` · davon ${r.workMinutes} an Arbeitsplätzen`:``}</p><dl><div><dt>Grundlohn</dt><dd>${euro(r.base)}</dd></div><div><dt>Qualitätsbonus</dt><dd>+ ${euro(r.bonus)}</dd></div><div><dt>Nacharbeit</dt><dd>− ${euro(r.deduction)}</dd></div><div class="receipt-total"><dt>Ausgezahlt</dt><dd>${euro(r.total)}</dd></div></dl></section>`;}
export function workshopCard(s,button,remote=false){
 const w=s.workshop,a=w.active;if(!a)return '<p class="lead">Noch kein Auftrag angenommen. Tessa erklärt dir die Arbeit am Empfang.</p>';
 const steps=workshopSteps(a),c=workshopStep(s),pay=workshopPayout(a,w.training),estimate=workshopEstimate(s);
 return `<div class="work-order"><span class="eyebrow">ARBEITSKARTE ${String(a.id).padStart(3,'0')} · ABGABE BIS 19:00</span><h3>${WORKSHOP_TYPES[a.type].name}</h3>${a.revision===2&&a.type!=='stock'?`<p>${orderBike(a).name} · ${orderBike(a).size} Zoll</p>`:``}${a.expressPart?'<p class="positive">Ersatzteil aus deiner letzten Expresslieferung liegt bereit.</p>':''}${supplyPanel(s,button)}<p class="work-time-estimate ${estimate.tight?'routine-warning':''}">${estimate.tight?'Zeit wird knapp · ':''}Noch etwa ${estimate.minutes} Spielminuten für Arbeit und Wege in der Werkstatt bei ${s.settings.speed}×. Bis Ladenschluss: ${estimate.remaining} Spielminuten.<small>Schätzung ohne Anreise, Teilefahrt und zusätzliche Nacharbeit.</small></p><ol class="work-steps">${steps.map((v,i)=>`<li class="${i<a.step?'done':i===a.step?'current':''}"><span>${i<a.step?'✓':String(i+1).padStart(2,'0')}</span><div><strong>${v.title}</strong><small>${WORKSHOP_POINTS[v.point].name}</small></div></li>`).join('')}</ol><p>${c?'Nächster Schritt: <b>'+c.title+'</b>. Gehe zur goldenen Bodenmarkierung und drücke E.':'Alle Prüfungen abgeschlossen. Lass den Auftrag bei Tessa am Empfang abnehmen.'}</p><p class="footnote">${a.mistakes} Nacharbeiten · Auszahlung bei erfolgreicher Abnahme derzeit ${euro(pay.total)}. Werkstatträder bleiben beim Verlassen im Raum. Die reservierte Ersatzteilpackung kannst du draußen tragen. Der Auftrag bleibt bis 19:00 offen.</p>${!c&&!remote?button('Abnehmen lassen · '+euro(pay.total),'workshopFinish','','primary',!atWorkshop(s,'workshopDesk')):''}</div>`;
}
export function workshopDeskPanel(s,button){
 const w=s.workshop,a=w.active,t=WORKSHOP_TRAINING[w.training],taken=w.day===s.day?w.taken:0;
 const plan=supplyPlan(s),canSupply=!!plan&&s.minute+plan.totalMinutes+110<=1140;
 const canAccept=workshopHours(s).accept&&!s.job&&!a&&taken<4&&s.needs.energy>=15&&!(s.cafe?.phase==='open'&&s.cafe.config.staff<2);
 return hours(s)+`<div class="work-summary"><div><span class="eyebrow">DEINE PRAXIS</span><h3>${level(w)}</h3><p>${w.xp} Erfahrung · ${w.completed} Aufträge abgenommen</p></div><div><strong>${Math.max(0,4-taken)} / 4</strong><span>Aushilfsaufträge heute frei</span></div></div><p class="footnote">${w.life?.parked.length??0} weitere Fahrräder in Arbeit · ${w.life?.people.length??0} Kunden im Haus · ${w.expressStock??0} Express-Ersatzteile eingelagert</p>`+(a?workshopCard(s,button)+button('Auftrag ohne Lohn zurückgeben','workshopCancelReview','','secondary'):`<p class="lead">Sauber arbeiten, nachprüfen, dann abgeben. Die Arbeitskarte enthält alle nötigen Hinweise. Werkzeug und Ersatzteile stellt die Werkstatt.</p><div class="cards workshop-offers">${Object.entries(WORKSHOP_TYPES).map(([id,v])=>`<article class="card"><span class="tag">${w.training<v.level?'BASISKURS ERFORDERLICH':'AUSHILFSAUFTRAG'}</span><h3>${v.name}</h3><p>${v.description}</p><div class="price">${euro(v.base)}<small>Grundlohn · ${Math.round(workshopSteps({type:id,variant:0,revision:2}).reduce((n,c)=>n+c.minutes,0)*(1-w.training*.08))} Spielminuten Arbeit + Wege</small></div>${button('Auftrag annehmen','workshopAccept',id,'primary',!canAccept||w.training<v.level)}${id==='tube'?button('Mit Teilefahrt · +8 € / bis +2 € Bonus','workshopAcceptSupply','tube','secondary',!canAccept||w.training<1||!canSupply):''}${id==='tube'?`<p class="footnote">Teilefahrt: Westhafen → Wareneingang. ${plan?.distance??0} m je Richtung. ${canSupply?'Ein Tagesplatz für Fahrt und Reparatur.':'Bei diesem Tempo bleibt heute zu wenig Zeit. Starte morgens bei 1×.'}</p>`:''}</article>`).join('')}</div>${!canAccept?'<p class="routine-warning">Neue Aufträge brauchen freie Hände, mindestens 15 Energie, einen freien Tagesplatz und Annahmezeit. Einen anderen Auftrag musst du vorher abschließen.</p>':''}`)+`<div class="info-box">Fehler werden vor der Freigabe korrigiert: Der Schritt wird wiederholt. Je Nacharbeit 0,75 € Abzug, insgesamt höchstens 35 % des Grundlohns. Nur fehlerfreie Aufträge erhalten ${10+w.training*5} % Qualitätsbonus. Bezahlt wird ausschließlich nach Abnahme. Keine Auszahlung bei Abbruch oder Verstreichen der Frist.</div><h3 class="section-title">Weiterbildung in der Werkstatt</h3>${t?`<article class="work-training"><div><span class="eyebrow">STUFE ${w.training+1} / 2</span><h3>${t.name}</h3><p>${w.training===0?'Schaltet den Schlauchwechsel frei. ':''}Arbeitsschritte ${8*(w.training+1)} % kürzer gegenüber der Aushilfe. Fehlerfreier Qualitätsbonus ${15+w.training*5} %.</p><p>${w.xp} / ${t.xp} Erfahrung · ${t.minutes} Spielminuten Kurs · ${euro(t.cost)}</p></div>${button('Kurs ansehen','workshopTrainReview','','secondary',!!a||!!s.job||s.cafe?.phase==='open'||w.xp<t.xp||s.money<t.cost||!workshopHours(s).open||s.minute+t.minutes>1140)}</article>`:'<p class="positive">Beide Kurse abgeschlossen. 16 % kürzere Arbeitszeiten und 20 % Qualitätsbonus bei fehlerfreien Aufträgen.</p>'}${workshopReceipt(w)}${deliveryReceipt(w)}<div class="funds">Dein Bargeld <b>${euro(s.money)}</b></div>`;
}
export function workshopStationPanel(s,point,button){
 const a=s.workshop.active,c=workshopStep(s),name=WORKSHOP_POINTS[point]?.name||'Arbeitsplatz';
 if(a?.supply?.phase==='carrying'&&point==='workshopIntake')return supplyPanel(s,button)+button('Teile abgeben & Fahrt abrechnen','workshopSupplyDeliver','','primary',!atWorkshop(s,'workshopIntake'));
 if(a?.supply&&a.supply.phase!=='received'&&point==='workshopStock')return supplyPanel(s,button)+button('Weiter','close');
 if(!a)return `<p class="lead">${name}</p><p>Nimm zuerst einen Auftrag bei Tessa am Empfang an. Danach zeigt dir deine Arbeitskarte den passenden Arbeitsplatz.</p>${button('Zurück zur Werkstatt','close')}`;
 if(!c||c.point!==point)return workshopCard(s,button,true)+`<p class="routine-warning">${c?'Dein nächster Arbeitsschritt ist bei: '+WORKSHOP_POINTS[c.point].name+'.':'Bitte zur Abnahme an den Empfang gehen.'}</p>${button('Weiterarbeiten','close')}`;
 return `<span class="eyebrow">SCHRITT ${a.step+1} / ${workshopSteps(a).length} · ${WORKSHOP_TYPES[a.type].name.toUpperCase()}</span><h3 class="work-task-title">${c.title}</h3><div class="work-instruction"><span>ARBEITSKARTE / BEFUND</span><p>${c.hint}</p></div><p class="lead">Wie gehst du vor?</p><div class="work-choices">${c.choices.map(([id,label])=>button(label,'workshopStep',id,'secondary',!atWorkshop(s,point))).join('')}</div><p class="footnote">${Math.round(c.minutes*(1-s.workshop.training*.08))} Spielminuten bei richtiger Ausführung. Die Arbeit beginnt nach deiner Auswahl im Raum. Escape pausiert auch den Arbeitsfortschritt.</p>${!atWorkshop(s,point)?'<p class="routine-warning">Gehe etwas näher an die goldene Bodenmarkierung heran.</p>':''}`;
}
export function workshopHud(s){
 const a=s.workshop.active;if(!a||s.interior!=='workshop')return '';const c=workshopStep(s),t=a.action,remaining=Math.max(0,Math.ceil(a.deadline-(s.day*1440+s.minute))),progress=t?t.elapsed/t.duration:a.step/workshopSteps(a).length;
 return `<section class="work-hud ${remaining<60?'urgent':''}"><span class="eyebrow">WERKSTATT · ${a.step} / ${workshopSteps(a).length} ERLEDIGT</span><strong>${c?c.title:'Bereit zur Abnahme'}</strong><span>${s.interior!=='workshop'?'Zurück zur Werkstatt West':t?t.approachDuration!=null&&t.age<t.approachDuration?'Geht zum Arbeitsplatz …':'In Arbeit · '+Math.ceil(t.duration-t.elapsed)+' Spielmin.':c?WORKSHOP_POINTS[c.point].name+' · E': 'Zu Tessa an den Empfang · E'}</span><div class="work-progress-label"><span>${t?'Arbeitsschritt':'Auftrag'}</span><b>${Math.round(progress*100)} %</b></div><progress max="1" value="${progress}" aria-label="${t?'Arbeitsfortschritt':'Abgeschlossene Arbeitsschritte'}"></progress><small>Abgabe bis 19:00 · noch ${remaining} Spielmin.</small>${s.workshop.feedback&&s.day*1440+s.minute-s.workshop.feedback.at<20?`<div class="work-feedback ${s.workshop.feedback.status}">${s.workshop.feedback.status==='correct'?'✓ Korrekt':'! Nacharbeit nötig'} · ${esc(s.workshop.feedback.title)}</div>`:``}${needsSupply(s)?`<div class="work-feedback">${a.supply.phase==='requested'?'Ersatzteil am Westhafen abholen':'Ersatzteil am Wareneingang abgeben'}</div>`:``}</section>`;
}

export function deliveryReceipt(w){const r=w.lastDelivery;if(!r)return '';return `<section class="courier-receipt"><span class="eyebrow">TEILEFAHRT · SEPARATE ABRECHNUNG</span><h3>Auftrag ${r.order}</h3><p>${r.duration} Spielminuten Rückweg · ${r.late?'Expressbonus verfallen':'Pünktlich am Wareneingang'}</p><dl><div><dt>Fahrtlohn</dt><dd>${euro(r.base)}</dd></div><div><dt>Expressbonus</dt><dd>${euro(r.bonus)}</dd></div><div class="receipt-total"><dt>Bereits ausgezahlt</dt><dd>${euro(r.total)}</dd></div></dl><p>Diese Auszahlung ist unabhängig von der anschließenden Reparatur.</p></section>`;}
export function supplyPanel(s,button){const p=s.workshop.active?.supply;if(!p)return '';const remaining=p.deadline==null?null:Math.ceil(p.deadline-s.day*1440-s.minute);return `<div class="work-instruction"><span>ERSATZTEILFAHRT / WESTHAFEN</span><p>${p.phase==='requested'?'Der passende Schlauch ist am Westhafen reserviert. Hole ihn ab und bringe ihn zum Wareneingang.':p.phase==='carrying'?'Ersatzteil übernommen. Gib es im Wareneingang der Werkstatt ab.':'Ersatzteil eingelagert. Du kannst es jetzt am Teilefach für die Reparatur auswählen.'}</p><small>Fahrtlohn 8 € · Expressbonus 2 € · ${remaining==null?'Die Bonusfrist beginnt bei Abholung.':remaining>=0?'Noch '+remaining+' Spielminuten für den Expressbonus.':'Bonusfrist verstrichen; der Fahrtlohn bleibt.'} Reparatur separat abrechenbar.</small>${p.phase==='carrying'&&p.speed!==s.settings.speed?'<p class="routine-warning">Tempo geändert: Die vereinbarte Bonusfrist bleibt bestehen.</p>':''}${p.phase!=='received'?button('Ziel markieren ↗','navigate',supplyTarget(s),'secondary'):''}</div>`;}
